/* ludcmp.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"

/* --------------------------------------------------------------------
 * Tunable parameters for optimization
 * --------------------------------------------------------------------
 * INIT_ARRAY_T_BLOCK controls blocking of the "t" dimension in the
 * initialization matrix product (A * A^T).  It can be tuned for a
 * specific cache hierarchy without changing the algorithm.
 */
#ifndef INIT_ARRAY_T_BLOCK
#  define INIT_ARRAY_T_BLOCK 32
#endif


/* Array initialization. */
static
void init_array (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
                 DATA_TYPE POLYBENCH_1D(b,N,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n),
                 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Initialize vectors b, x, y. */
  for (i = 0; i < n; i++)
    {
      x[i] = 0;
      y[i] = 0;
      b[i] = (i+1)/fn/2.0 + 4;
    }

  /* Initialize matrix A as in the original code. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
        A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++)
        A[i][j] = 0;
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite: A <- A * A^T.
     We keep the mathematical operation identical but reorganize the
     computation for better cache locality and (optional) parallelism. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  /* Create local restrict-qualified aliases to help the optimizer. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Compute B = A * A^T.
     - We exploit symmetry: B[r][s] == B[s][r], so each pair (r,s)
       is computed only once, halving the arithmetic work.
     - For each fixed (r,s), the accumulation over t is still
       performed in strictly increasing t order, preserving the
       original floating-point evaluation order for that element.
     - The outer loop over r can be parallelized safely because each
       B[r][s] is written exactly once by a single (r,s) pair. */

#pragma omp parallel for schedule(static) private(s,t) if (n > 64)
  for (r = 0; r < n; ++r)
    {
      const DATA_TYPE *restrict Ar = A_[r];

      for (s = r; s < n; ++s)
        {
          const DATA_TYPE *restrict As = A_[s];
          DATA_TYPE sum = 0;

          /* Optional blocking in the t-dimension.
             The inner t-loop still traverses t from 0 to n-1 in order,
             just grouped in blocks of INIT_ARRAY_T_BLOCK. */
          for (int tt = 0; tt < n; tt += INIT_ARRAY_T_BLOCK)
            {
              int t_end = tt + INIT_ARRAY_T_BLOCK;
              if (t_end > n)
                t_end = n;

              for (t = tt; t < t_end; ++t)
                sum += Ar[t] * As[t];
            }

          B_[r][s] = sum;
          B_[s][r] = sum; /* Exploit symmetry. When r == s this is a no-op. */
        }
    }

  /* Copy the symmetric positive semi-definite matrix back into A. */
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A_[r][s] = B_[r][s];

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("x");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, x[i]);
  }
  POLYBENCH_DUMP_END("x");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp [[gnu::flatten, gnu::noinline]] (int n,
                 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
                 DATA_TYPE POLYBENCH_1D(b,N,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n),
                 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  const int nPB = _PB_N; /* PolyBench's possibly adjusted problem size. */
  (void)n;               /* n is kept for interface compatibility. */

  /* Local restrict-qualified aliases improve compiler optimization,
     while using 'n' for the declared extent keeps the types compatible
     with the PolyBench allocation macros. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict b_ = b;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict y_ = y;

  /* Temporary buffer used to update the U part of each row.
     Size is nPB (the maximum number of columns updated at once). */
  DATA_TYPE tmp_row[nPB];

#pragma scop
  /* LU decomposition: A is overwritten in-place with L and U.
     L is stored in the strictly lower part of A (unit diagonal
     is implicit) and U in the upper part (including the diagonal). */
  for (i = 0; i < nPB; i++) {
    DATA_TYPE *restrict Ai = A_[i];

    /* Compute the lower-triangular entries L(i,0..i-1). */
    for (j = 0; j < i; j++) {
      DATA_TYPE w = Ai[j];

      /* Dot product of row i (L part) with column j (U part). */
      for (k = 0; k < j; k++) {
        w -= Ai[k] * A_[k][j];
      }

      Ai[j] = w / A_[j][j];
    }

    /* Compute the upper-triangular entries U(i,i..nPB-1).

       Original code (for a fixed i):
         for (j = i; j < nPB; ++j) {
           w = A[i][j];
           for (k = 0; k < i; ++k)
             w -= A[i][k] * A[k][j];
           A[i][j] = w;
         }

       This has a poor memory-access pattern for A[k][j] because k is
       the inner loop index and A is stored in row-major order, so
       A[k][j] is accessed with a large stride.

       We restructure the computation so that, for each row i, we:
         1. Copy A[i][j] for j >= i into a contiguous temporary buffer.
         2. For each k < i, perform a rank-1 update over all j >= i,
            with the inner loop traversing contiguous memory in A_[k].
         3. Copy the updated values back into A[i][j].

       For each fixed column j, the sequence of floating-point
       operations on that entry is *identical* to the original:
         w_j starts at A[i][j] and we subtract A[i][k] * A[k][j]
         for k = 0..i-1 in that order.  We merely interleave updates
       for different j values, which are independent.  Thus the
       numerical semantics for each A[i][j] are preserved. */
    {
      const int len = nPB - i; /* Number of columns j >= i. */

      /* Step 1: copy current row segment into tmp_row. */
      for (j = 0; j < len; ++j)
        tmp_row[j] = Ai[i + j];

      /* Step 2: apply contributions from previously computed rows. */
      for (k = 0; k < i; ++k) {
        const DATA_TYPE Lik = Ai[k];
        const DATA_TYPE *restrict Ak = A_[k];

        /* Inner loop over contiguous columns j >= i. */
        for (j = 0; j < len; ++j)
          tmp_row[j] -= Lik * Ak[i + j];
      }

      /* Step 3: write back the updated U row segment. */
      for (j = 0; j < len; ++j)
        Ai[i + j] = tmp_row[j];
    }
  }

  /* Forward substitution: solve L * y = b.
     L has unit diagonal (implicitly 1.0 on the diagonal). */
  for (i = 0; i < nPB; i++) {
    const DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE w = b_[i];

    for (j = 0; j < i; j++)
      w -= Ai[j] * y_[j];

    y_[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = nPB-1; i >= 0; i--) {
    const DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE w = y_[i];

    for (j = i+1; j < nPB; j++)
      w -= Ai[j] * x_[j];

    x_[i] = w / Ai[i];
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);
  POLYBENCH_1D_ARRAY_DECL(b, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);


  /* Initialize array(s). */
  init_array (n,
              POLYBENCH_ARRAY(A),
              POLYBENCH_ARRAY(b),
              POLYBENCH_ARRAY(x),
              POLYBENCH_ARRAY(y));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_ludcmp (n,
                 POLYBENCH_ARRAY(A),
                 POLYBENCH_ARRAY(b),
                 POLYBENCH_ARRAY(x),
                 POLYBENCH_ARRAY(y));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(x)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(b);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);

  return 0;
}
