 */
/* ludcmp.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "ludcmp.h"


/* Array initialization. */
static
void init_array (int n,
		 DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		 DATA_TYPE POLYBENCH_1D(b,N,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Use restrict-qualified local pointers to help the compiler
     with alias analysis and vectorization. PolyBench allocators
     guarantee that these arrays do not alias each other. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict b_ = b;
  DATA_TYPE *restrict x_ = x;
  DATA_TYPE *restrict y_ = y;

  /* Initialize x, y, and b. */
  for (i = 0; i < n; i++)
    {
      x_[i] = (DATA_TYPE)0;
      y_[i] = (DATA_TYPE)0;
      /* Same formula as the original: (i+1)/n/2 + 4. */
      b_[i] = (DATA_TYPE)(i + 1) / fn / (DATA_TYPE)2.0 + (DATA_TYPE)4.0;
    }

  /* Initialize A as in the original code, but avoid the expensive
     modulus operation.  For 0 <= j < n we have (-j % n) == -j in C,
     so (-j % n) / n + 1 is equal to (-j) / n + 1. */
  for (i = 0; i < n; i++)
    {
      DATA_TYPE *restrict Ai = A_[i];

      for (j = 0; j <= i; j++)
	Ai[j] = (DATA_TYPE)(-j) / fn + (DATA_TYPE)1.0;

      for (j = i+1; j < n; j++)
	Ai[j] = (DATA_TYPE)0.0;

      Ai[i] = (DATA_TYPE)1.0;
    }

  /* Make the matrix positive semi-definite.
     We compute B = A * A^T and then copy B back into A.

     Compared to the original triple loop:
       - we exploit the symmetry of B (B[r][s] == B[s][r])
         and compute only the upper triangle, mirroring it to
         the lower triangle; this halves the arithmetic work.
       - for each element B[r][s], we still accumulate over t
         in the order t = 0..n-1, exactly as in the original
         implementation, so the floating-point summation order
         for every B[r][s] is preserved.
  */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);
  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  for (r = 0; r < n; ++r)
    {
      const DATA_TYPE *restrict Ar = A_[r];

      for (s = r; s < n; ++s)
        {
          const DATA_TYPE *restrict As = A_[s];
          DATA_TYPE sum = (DATA_TYPE)0.0;

          /* Accumulate in t from 0 to n-1, same as in the original. */
          for (t = 0; t < n; ++t)
            sum += Ar[t] * As[t];

          B_[r][s] = sum;
          if (s != r)
            B_[s][r] = sum;  /* exploit symmetry */
        }
    }

  /* Copy B back into A. */
  for (r = 0; r < n; ++r)
    {
      DATA_TYPE *restrict Ar = A_[r];
      const DATA_TYPE *restrict Br = B_[r];
      for (s = 0; s < n; ++s)
        Ar[s] = Br[s];
    }

  POLYBENCH_FREE_ARRAY(B);
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(x,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
