  DATA_TYPE fn = (DATA_TYPE)n;

  /* Initialize right-hand side and solution vectors. */
  for (i = 0; i < n; i++)
    {
      x[i] = 0;
      y[i] = 0;
      b[i] = (i+1)/fn/2.0 + 4;
    }

  /* Initialize A as a lower triangular matrix with unit diagonal. */
  for (i = 0; i < n; i++)
    {
      for (j = 0; j <= i; j++)
	A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
      for (j = i+1; j < n; j++)
	A[i][j] = 0;
      A[i][i] = 1;
    }

  /* Make the matrix positive semi-definite.
     This is not necessary for LU itself but keeps the behavior
     identical to the original PolyBench code that shares this
     initializer with the Cholesky benchmark.

     We compute:
       B = A * A^T
     and then copy B back into A.

     The implementation below:
       - exploits symmetry (computes only r <= s, mirrors to s,r),
       - uses contiguous accesses in the innermost t-loop,
       - parallelizes the (r,s) and copy loops with OpenMP. */
  int r, s, t;
  POLYBENCH_2D_ARRAY_DECL(B, DATA_TYPE, N, N, n, n);

  DATA_TYPE (*restrict B_)[n] = POLYBENCH_ARRAY(B);

  /* Compute upper triangle (including diagonal) of B and mirror. */
#pragma omp parallel for collapse(2) schedule(static) if (n >= LUDCMP_INIT_OMP_MIN_N)
  for (r = 0; r < n; ++r)
    for (s = r; s < n; ++s)
      {
        DATA_TYPE acc = 0;
        for (t = 0; t < n; ++t)
          acc += A[r][t] * A[s][t];
        B_[r][s] = acc;
        if (s != r)
          B_[s][r] = acc;
      }

  /* Copy B back into A. */
#pragma omp parallel for collapse(2) schedule(static) if (n >= LUDCMP_INIT_OMP_MIN_N)
  for (r = 0; r < n; ++r)
    for (s = 0; s < n; ++s)
      A[r][s] = B_[r][s];

  POLYBENCH_FREE_ARRAY(B);
