/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_ludcmp[[gnu::flatten, gnu::noinline]](int n,
		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;

#pragma scop
  /* LU factorization with in-place storage of L and U in A.
     We parallelize the computation of the upper-triangular part U
     across columns for each row, while the lower-triangular part L
     and the triangular solves remain sequential in the row index. */
#pragma omp parallel if (_PB_N >= LUDCMP_OMP_MIN_N) private(i, j, k)
  {
    /* -------------------- Factorization: A = L * U -------------------- */
    for (i = 0; i < _PB_N; i++)
      {
        /* All threads compute the same row index i but have private
           loop variables.  Each thread gets its own pointer to A[i]. */
        DATA_TYPE *restrict Ai = A[i];

        /* ---- Step 1: compute L(i,0..i-1) (lower triangular part) ----
           This step is inherently sequential in j: L(i,j) depends on
           L(i,0..j-1).  Execute it on a single thread, with an
           implicit barrier at the end so that all threads see the
           updated L row before proceeding. */
#pragma omp single
        {
          for (j = 0; j < i; j++)
            {
              DATA_TYPE w = Ai[j];
              for (k = 0; k < j; k++)
                w -= Ai[k] * A[k][j];
              w /= A[j][j];
              Ai[j] = w;
            }
        } /* implicit barrier here */

        /* ---- Step 2: compute U(i,i..N-1) (upper triangular part) ----
           For fixed i, each column j >= i is independent once the
           L(i,0..i-1) entries are known, so we parallelize the j-loop.

           Each iteration only updates Ai[j] and reads Ai[0..i-1] and
           A[0..i-1][j], so there are no cross-iteration dependencies. */
#pragma omp for schedule(static)
        for (j = i; j < _PB_N; j++)
          {
            DATA_TYPE w = Ai[j];
            for (k = 0; k < i; k++)
              w -= Ai[k] * A[k][j];
            Ai[j] = w;
          }
        /* implicit barrier at end of 'omp for':
           row i is fully updated before any thread moves to row i+1 */
      } /* end for i */

    /* ---------------- Triangular solves (sequential in i) -------------- */
#pragma omp single
    {
      /* Forward substitution: solve L * y = b.
         We keep the i-loop sequential but vectorize the inner product
         over j using 'omp simd'. */
      for (i = 0; i < _PB_N; i++)
        {
          DATA_TYPE sum = 0;
          DATA_TYPE *restrict Ai = A[i];

          /* y[0..i-1] are already computed and read-only here. */
#pragma omp simd reduction(+:sum)
          for (j = 0; j < i; j++)
            sum += Ai[j] * y[j];

          y[i] = b[i] - sum;
        }

      /* Backward substitution: solve U * x = y. */
      for (i = _PB_N - 1; i >= 0; i--)
        {
          DATA_TYPE sum = 0;
          DATA_TYPE *restrict Ai = A[i];

          /* x[i+1..N-1] are already computed and read-only here. */
#pragma omp simd reduction(+:sum)
          for (j = i + 1; j < _PB_N; j++)
            sum += Ai[j] * x[j];

          x[i] = (y[i] - sum) / Ai[i];
        }
    } /* end single (solves) */
  }   /* end parallel region */
#pragma endscop

}


