		   DATA_TYPE POLYBENCH_2D(A,N,N,n,n),
		   DATA_TYPE POLYBENCH_1D(b,N,n),
		   DATA_TYPE POLYBENCH_1D(x,N,n),
		   DATA_TYPE POLYBENCH_1D(y,N,n))
{
  int i, j, k;
  DATA_TYPE w;

  /* Precompute and cache reciprocals of the diagonal entries of U.
     This replaces O(n^2) divisions by O(n^2) multiplications +
     O(n) divisions.  The diagonal A[i][i] is finalized before it is
     ever used, so we can safely store its reciprocal and reuse it.
     The order of floating-point operations for each row is preserved. */
  DATA_TYPE inv_diag[_PB_N];

#pragma scop
  /* LU factorization (Doolittle without pivoting). */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];

    /* Compute elements of L in row i (columns 0..i-1). */
    for (j = 0; j < i; j++) {
      w = Ai[j];
      /* Dot-product-like update: uses row i and column j. */
      for (k = 0; k < j; k++) {
        w -= Ai[k] * A[k][j];
      }
      /* A[j][j] is finalized when row j is processed, and
         inv_diag[j] holds 1 / A[j][j]. */
      Ai[j] = w * inv_diag[j];
    }

    /* Compute elements of U in row i (columns i..n-1). */
    for (j = i; j < _PB_N; j++) {
      w = Ai[j];
      /* Dot-product-like update: uses row i and column j. */
      for (k = 0; k < i; k++) {
        w -= Ai[k] * A[k][j];
      }
      Ai[j] = w;
    }

    /* Cache the reciprocal of the newly computed diagonal element.
       It will be used in later rows and in the back-substitution. */
    inv_diag[i] = (DATA_TYPE)1.0 / Ai[i];
  }

  /* Forward substitution: solve L * y = b.
     L has unit diagonal, so no division is required here. */
  for (i = 0; i < _PB_N; i++) {
    DATA_TYPE *Ai = A[i];
    w = b[i];
    for (j = 0; j < i; j++)
      w -= Ai[j] * y[j];
    y[i] = w;
  }

  /* Backward substitution: solve U * x = y. */
  for (i = _PB_N-1; i >= 0; i--) {
    DATA_TYPE *Ai = A[i];
    w = y[i];
    for (j = i+1; j < _PB_N; j++)
      w -= Ai[j] * x[j];
    /* Use precomputed reciprocal of A[i][i]. */
    x[i] = w * inv_diag[i];
  }
